/* eslint-disable @typescript-eslint/restrict-template-expressions */
/* eslint-disable @typescript-eslint/no-unsafe-return */
import { ref } from 'vue';
import { LocalStorage } from 'quasar';
import { userApiService } from 'src/services';
import documentUtil from 'src/utils/documentUtil';
import { useDocumentStore } from 'src/store/main';
import { splitDelimiter, tableRowIdPreFix } from 'src/constants';
import { cleanUpImagesUrl, cleanUpImagePath } from 'src/utils/viewImages';

const $ = document.querySelector.bind(document);
export default {
  mixins: [documentUtil],
  setup() {
    const doc_store = useDocumentStore();
    const { field_view_mode } = storeToRefs(doc_store);

    return {
      field_view_mode,
    };
  },
  data() {
    return {
      mousedown: ref(false), // state mouse down event
      originImgSize: {
        // root size image
        w: 0,
        h: 0,
        r: 0,
      },
      url: this.cropUrl,
      posImg: {
        // position box image in screen
        top: 0,
        left: 0,
      },
      currentSelectedItem: ref(),
      latestAreaItem: { startX: 0, startY: 0, endX: 0, endY: 0 },
      scrollLeft: 0,
      scrollTop: 0,
      moveTempX: 0,
      moveTempY: 0,
      moveCurrentX: 0,
      moveCurrentY: 0,
      temp: 0,
      dragdown: false, // state mouse event drag,
      move: false,
      imageHeight: 0,
      imageWidth: 0,
      correctionDialog: false,
      numberOfAreas: 0,
      oldArea: '',
      disableImageRowsClick: false,
      delay: 170,
      clicks: 0,
      timer: ref(),
      delay2: ref(170),
      timer2: ref(),
    };
  },
  methods: {
    addEvents() {
      this.screenshot.addEventListener('pointerdown', this.startDrag);
      document.body.addEventListener('click', this.mouseClicked, true);

      const splitter__before = $('.right_section');
      if (splitter__before) {
        splitter__before.addEventListener('scroll', this.removeOverlayandLines);
      }
    },
    removeEvents() {
      this.screenshot.removeEventListener('dblclick', this.dblClickToSelect);
      this.screenshot.removeEventListener('pointerdown', this.startDrag);
      document.body.removeEventListener('click', this.mouseClicked, true);

      const splitter__before = $('.right_section');
      if (splitter__before) {
        splitter__before.removeEventListener(
          'scroll',
          this.removeOverlayandLines,
        );
      }
    },

    initImageArea() {
      // Use jQuery selectors for elements not managed by Vue refs
      this.areas = $('#areas');

      // Note: screenshot, marquee, and boxes are Vue template refs
      // They are auto-unwrapped when accessed via 'this' in Options API methods
      // DO NOT reassign them with jQuery - let Vue manage the binding

      if (this.marquee) this.marquee.classList.add('hide');

      // set the width of image
      let imageElm = $('#image_container');
      if (!imageElm) {
        return;
      }
      this.imageWidth = imageElm.offsetWidth;
      this.imageHeight = imageElm.offsetHeight;
      this.viewBox =
        '0 0 ' + String(this.imageWidth) + ' ' + String(this.imageHeight);

      // double click to select
      if (this.screenshot) {
        this.screenshot.addEventListener('dblclick', this.dblClickToSelect);
        this.screenshot.addEventListener('pointerdown', this.startDrag);
      }
    },
    mouseClicked(e) {
      this.removeMagnifier();
    },
    mousePosX(e) {
      return e.pageX - this.posImg.left;
    },
    mousePosY(e) {
      return e.pageY - this.posImg.top;
    },
    removeMagnifier() {
      const glassBtn = $('#glassBtn');
      if (glassBtn) {
        glassBtn.classList.remove('glass-active');
      }

      // const glass = document.getElementById('zoom') as HTMLElement;
      let glass = document.querySelector('.img-magnifier-glass');
      if (glass) {
        glass.style.display = 'none';
        glass.classList.remove('enable-glass');
        glass.removeEventListener('pointermove', this.moveMagnifier);
      }

      const draw = $('#draw');
      if (draw) {
        draw.removeEventListener('pointermove', this.moveMagnifier);
      }

      document.body.classList.remove('active');
      this.magnifyGlass = null;
      // this.restrictDrawing();
    },
    initMagnifyGlass() {
      this.removeOverlayandLines();
      this.restrictDrawing();

      let screenshot = $('.screenshot');
      let glass = document.querySelector('.img-magnifier-glass');
      if (!glass) {
        return;
      }
      const zoom = 3;
      glass.style.display = 'block';
      glass.style.backgroundImage = "url('" + screenshot.src + "')";
      glass.style.backgroundRepeat = 'no-repeat';
      glass.style.backgroundSize =
        screenshot.width * zoom + 'px ' + screenshot.height * zoom + 'px';
      const bw = 3;
      const w = glass.offsetWidth / 2;
      const h = glass.offsetHeight / 2;

      this.magnifyGlass = {
        Ix: screenshot.offsetLeft,
        Iy: screenshot.offsetTop,
        Zw: glass.offsetWidth,
        Zh: glass.offsetHeight,
        w: w,
        h: h,
        bw: bw,
        ratio: screenshot.naturalWidth / screenshot.width,
      };

      const draw = $('#draw');
      draw.removeEventListener('pointermove', this.moveMagnifier);
      glass.removeEventListener('pointermove', this.moveMagnifier);

      draw.addEventListener('pointermove', this.moveMagnifier);
      glass.addEventListener('pointermove', this.moveMagnifier);
    },

    moveMagnifier(event) {
      const zoom = 3;
      var pos, x, y;
      let glass = document.querySelector('.img-magnifier-glass');
      let screenshot = $('.screenshot');
      /*prevent any other actions that may occur when moving over the image*/
      event.preventDefault();
      /*get the cursor's x and y positions:*/
      pos = this.getCursorPos(event);
      x = pos.x;
      y = pos.y;
      /*prevent the magnifier glass from being positioned outside the image:*/
      if (x > screenshot.width - this.magnifyGlass.w / zoom) {
        x = screenshot.width - this.magnifyGlass.w / zoom;
      }
      if (x < this.magnifyGlass.w / zoom) {
        x = this.magnifyGlass.w / zoom;
      }
      if (y > screenshot.height - this.magnifyGlass.h / zoom) {
        y = screenshot.height - this.magnifyGlass.h / zoom;
      }
      if (y < this.magnifyGlass.h / zoom) {
        y = this.magnifyGlass.h / zoom;
      }
      /*set the position of the magnifier glass:*/
      glass.style.left = x - this.magnifyGlass.w + 'px';
      glass.style.top = y - this.magnifyGlass.h + 'px';
      /*display what the magnifier glass "sees":*/
      glass.style.backgroundPosition =
        '-' +
        (x * zoom - this.magnifyGlass.w + this.magnifyGlass.bw) +
        'px -' +
        (y * zoom - this.magnifyGlass.h + this.magnifyGlass.bw) +
        'px';
    },
    getCursorPos(e) {
      var a,
        x = 0,
        y = 0;
      e = e || window.event;
      /*get the x and y positions of the image:*/
      let img = $('.screenshot');
      a = img.getBoundingClientRect();
      /*calculate the cursor's x and y coordinates, relative to the image:*/
      x = e.pageX - a.left;
      y = e.pageY - a.top;
      /*consider any page scrolling:*/
      x = x - window.pageXOffset;
      y = y - window.pageYOffset;
      return { x: x, y: y };
    },

    startDrag(ev) {
      if (!this.screenshot.classList.contains('cursor-crosshair')) {
        return;
      }
      let height = 0;
      let width = 0;
      if (ev.button === 1) {
        const rect = this.hitTest(ev.layerX, ev.layerY);
        if (rect) {
          this.rectangles.splice(this.rectangles.indexOf(rect), 1);
          this.redraw();
        }
        return;
      }

      this.marquee.classList.remove('hide');
      let startX = (this.startX = ev.layerX);
      let startY = (this.startY = ev.layerY);
      let connectionId = '';
      Object.assign(this.marqueeRect, {
        startX,
        startY,
        width,
        height,
        connectionId,
      });
      this.drawRect(this.marquee, this.marqueeRect);

      if (this.field_view_mode == 'validate') {
        window.addEventListener('pointerup', this.stopDragValidate);
        this.screenshot.addEventListener('pointermove', this.moveDrag);
      } else {
        this.mouseDownAnnotate(ev);
        window.addEventListener('pointerup', this.endDragAnnotate);
        this.screenshot.addEventListener('pointermove', this.moveDrag);
        this.screenshot.addEventListener('mousemove', this.mouseMoveAnnotate);
      }
    },

    moveDrag(ev) {
      let startX = this.startX;
      let startY = this.startY;
      let x = ev.layerX;
      let y = ev.layerY;
      let endX = ev.layerX;
      let endY = ev.layerY;
      let width = this.startX - x;
      let height = this.startY - y;
      if (width < 0) {
        width *= -1;
        x -= width;
      }
      if (height < 0) {
        height *= -1;
        y -= height;
      }
      let connectionId = '';
      Object.assign(this.rectCordinate, { startX, startY, endX, endY });
      Object.assign(this.marqueeRect, { x, y, width, height, connectionId });
      this.drawRect(this.marquee, this.marqueeRect);
    },

    stopDragValidate(ev) {
      this.marquee.classList.add('hide');
      window.removeEventListener('pointerup', this.stopDragValidate);
      screenshot.removeEventListener('pointermove', this.moveDrag); //.bind(this)
      //  ev.target.removeEventListener('pointerup', this.stopDrag.bind(this));
      //  ev.target.removeEventListener('pointermove', this.moveDrag.bind(this));//.bind(this)
      if (
        ev.target === this.screenshot &&
        this.marqueeRect.width &&
        this.marqueeRect.height
      ) {
        if (this.connectionId) {
          this.marqueeRect.connectionId = this.connectionId;
        }
        this.rectangles.push(Object.assign({}, this.marqueeRect));
        this.redraw();
        this.restrictDrawing();
        this.saveOverlayResult();
      }
    },

    endDragAnnotate() {
      window.removeEventListener('pointerup', this.endDragAnnotate);
      screenshot.removeEventListener('pointermove', this.moveDrag);
      screenshot.removeEventListener('mousemove', this.mouseMoveAnnotate);
      this.mouseUpAnnotate();
    },

    mouseDownAnnotate(e) {
      this.mousedown = true;
      let newAreaId = null;

      if (this.areas == undefined) {
        this.areas = [];
      } else if (this.areas.length > 0) {
        // last area id + 1
        newAreaId = this.areas.slice(-1).pop().id + 1;
      } else {
        newAreaId = 1;
      }

      this.numberOfAreas = newAreaId;

      if (
        this.latestAreaItem.startX != 0 &&
        this.latestAreaItem.startY != 0 &&
        this.isRowMode === false
      ) {
        let startX = this.latestAreaItem.startX;
        let startY = this.latestAreaItem.startY;

        let endX = e.layerX;
        let endY = e.layerY;

        let width = endX - startX;
        let height = endY - startY;
        if (width < 0 || height < 0) {
          endX = startX;
          endY = startY;

          startX = e.layerX;
          startY = e.layerY;

          width = endX - startX;
          height = endY - startY;
        }

        let newArea = {
          id: newAreaId,
          x: startX,
          y: startY,
          startX: startX,
          startY: startY,
          width: width,
          height: height,
          z: 0,
          resizable: false,
          opacity: '1',
          background: this.isRowMode ? rowRgbaColorStr : '',
          areaTag: this.isRowMode ? 'column' : 'table',
          areaType: this.isRowMode ? 'column' : 'table',
          rowId: '',
        };
        this.temp = newArea.id;
        this.areas.push(newArea);
        this.latestAreaItem = { startX: 0, startY: 0, endX: 0, endY: 0 };
        return;
      }

      if (newAreaId) {
        let newArea = {
          id: newAreaId,
          x: this.mousePosX(e),
          y: this.mousePosY(e),
          startX: this.mousePosX(e),
          startY: this.mousePosY(e),
          width: 0,
          height: 0,
          z: 0,
          resizable: false,
          opacity: '1',
          background: this.isRowMode ? rowRgbaColorStr : '',
          areaTag: this.isRowMode ? 'column' : 'table',
          areaType: this.isRowMode ? 'column' : 'table',
          rowId: '',
        };
        this.areas.push(newArea);
        this.temp = newArea.id;
        this.latestAreaItem.startX = this.mousePosX(e);
        this.latestAreaItem.startY = this.mousePosY(e);
        this.latestAreaItem.endX = 0;
        this.latestAreaItem.endY = 0;
      }
    },

    mouseMoveAnnotate(e) {
      this.areas
        .filter((x) => x.id === this.temp)
        .map((item) => {
          let x = e.pageX - this.posImg.left;
          let y = e.pageY - this.posImg.top;
          let width = item.startX - x;
          let height = item.startY - y;
          if (width < 0) {
            width *= -1;
            x -= width;
          }
          if (height < 0) {
            height *= -1;
            y -= height;
          }

          item.x = x;
          item.y = y;
          item.width = width;
          item.height = height;
        });
      this.latestAreaItem = { startX: 0, startY: 0, endX: 0, endY: 0 };
    },

    mouseUpAnnotate() {
      this.timer2 = setTimeout(() => {
        this.mousedown = false;
        // delete all point width is less then 3
        this.areas = this.areas.filter(
          (item) => item.width >= 3 && item.height >= 3,
        );
        // this.setTableAreas();

        // check if mode is row and new area on image is created
      }, this.delay2);
    },

    changeResizable(id) {
      this.areas
        .filter((item) => item.id === id)
        .map((item) => {
          item.resizable = true;
          item.z = 100;
        });
      this.areas
        .filter((item) => item.id !== id)
        .map((item) => {
          item.resizable = false;
          item.z = 0;
        });
    },
    // delete item area
    deleteSelected(id) {
      this.areas = this.areas.filter((item) => item.id !== id);
      this.prepareTableArea();
    },

    decideAction(item) {
      let areaTag = item.areaTag;
      let areaType = item.areaType;
      let rowId = item.rowId;

      this.currentSelectedItem = item;
      this.removeExistingConfirmationOverlays();

      if (this.disableImageRowsClick === true) {
        return;
      }

      this.disableSelectionForRow(this.oldArea);

      if (areaType === 'column') {
        this.numberOfAreas = 0;

        // clear old selection

        let image_container_el = $('#screenshot_container');

        let columnAreas = image_container_el.querySelectorAll(
          'div.column_background_area',
        );
        Array.from(columnAreas).forEach((element) => {
          let selectionBackground = element.style.background.split('100%)');
          element.style.background = rowRgbaColor + selectionBackground[1];
        });

        let imageArea =
          image_container_el.querySelectorAll('div.column_outline');
        Array.from(imageArea).forEach((element) => {
          element.style.opacity = '0.2';
          if (element.nextSibling) {
            element.nextSibling.style.border = 'unset';
          }
        });

        this.oldArea = rowId;
        let selectedInput = $('#' + 'input_' + areaTag + '_' + rowId);

        if (selectedInput) {
          let selectedArea = $('#' + 'draw_' + areaTag);

          let selectedAreaBorderElm = selectedArea.querySelector(
            '.select-areas--outline',
          );
          selectedAreaBorderElm.style.opacity = '0';

          let elems = document
            .querySelector('#line_item_table')
            .querySelectorAll('label.active-border-2px');
          Array.from(elems).forEach((element) => {
            element.classList.remove('active-border-2px');
          });

          let selection = selectedArea.querySelector(
            '.select-areas--background_area',
          );
          selection.style.border = '2px';
          selection.style.borderStyle = 'solid';
          selection.style.borderColor = '#8800ff';

          selectedInput.scrollIntoView();
          selectedInput
            .querySelector('label')
            .classList.add('active-border-2px');

          let extraction_method_els = selectedInput.querySelector(
            'label.extraction_method',
          );

          if (extraction_method_els != null) {
            let column_value = selectedInput.dataset.columnValue;
            let score_description = selectedInput.dataset.scoreDescription;
            let detailObj = {
              value: column_value,
              score: score_description,
              selection: selection,
            };

            this.prepareOverlay({ detail: detailObj });
          }
        } else {
          logError('not mapped');
        }
      } else {
        this.numberOfAreas = 0;

        // high light selected row
        let selectedRow = document.getElementById(areaTag);
        selectedRow.classList.add('active-table-row');

        // remove old high light selected row
        if (this.oldArea != '') {
          let oldSelectedRow = document.getElementById(this.oldArea);
          oldSelectedRow.classList.remove('active-table-row');
        }

        let detailObj = { rowId: areaTag, columnName: null };
        const event = new CustomEvent('get_table_rows_areas', {
          detail: detailObj,
        });
        document.dispatchEvent(event);

        this.oldArea = areaTag;
      }
    },

    enableSelectionForRow(e) {
      this.disableImageRowsClick = true;
      this.disableSelectionForRow(this.oldArea);

      let areaTag = e.detail;
      this.oldArea = e.detail;
      let selectedRow = $('#' + 'draw_' + areaTag).querySelector(
        '.select-areas--background_area',
      );

      selectedRow.style.cursor = 'crosshair';
      selectedRow.addEventListener('mousedown', this.manageEventsForColumns);
    },
    disableSelectionForRow(oldArea) {
      if (oldArea != '') {
        if ($('#' + 'draw_' + oldArea)) {
          let oldElement = $('#' + 'draw_' + oldArea).querySelector(
            '.select-areas--background_area',
          );

          oldElement.style.cursor = 'pointer';
          oldElement.removeEventListener(
            'mousedown',
            this.manageEventsForColumns,
          );
          oldElement.removeEventListener('mousemove', this.mouseMove);
        }
      }
    },
    dblClickToSelect(ev) {
      this.disableSelectionForRow(this.oldArea);
      let coord = this.getTableAreaAsString(
        this.mousePosX(ev),
        this.mousePosY(ev),
        this.mousePosX(ev),
        this.mousePosY(ev),
      );
      this.$emit('saveColumnCoords', coord);
    },

    hitTest(x, y) {
      return this.rectangles.find(
        (rect) =>
          x >= rect.x &&
          y >= rect.y &&
          x <= rect.x + rect.width &&
          y <= rect.y + rect.height,
      );
    },
    redraw() {
      const boxes = this.boxes || $('#boxes');
      if (!boxes) {
        return;
      }

      boxes.innerHTML = '';
      this.rectangles.forEach((data) => {
        boxes.appendChild(
          this.drawRect(
            document.createElementNS('http://www.w3.org/2000/svg', 'rect'),
            data,
          ),
        );
      });
    },
    drawRect(rect, data) {
      if (typeof data == 'object') {
        let classes = 'cursor-pointer';

        const { x, y, width, height, connectionId } = data;
        rect.setAttributeNS(null, 'width', width);
        rect.setAttributeNS(null, 'height', height);
        rect.setAttributeNS(null, 'x', x);
        rect.setAttributeNS(null, 'y', y);
        rect.setAttributeNS(null, 'connectionId', connectionId);

        // this.foreignObject.setAttributeNS(null, 'width', width);
        // this.foreignObject.setAttributeNS(null, 'height', height);
        // this.foreignObject.setAttributeNS(null, 'x', x);
        // this.foreignObject.setAttributeNS(null, 'y', y);

        if (connectionId && this.field_view_mode == 'validate') {
          rect.setAttributeNS(null, 'id', connectionId + '_rect');

          let fieldArr = Array.isArray(this.record?.fields)
            ? this.record.fields.filter((field) => connectionId == field.name)
            : [];
          const field = fieldArr.length > 0 ? fieldArr.pop() : {};

          // Add class for TRocr field
          if (
            field.hasOwnProperty('trocr_processor') &&
            field.trocr_processor != ''
          ) {
            classes += ' extract_by_tcocr ';
          } else if (connectionId.startsWith(tableRowIdPreFix)) {
            classes += ' ai_table_row ';
          }
        }
        rect.setAttributeNS(null, 'class', classes);

        // if (this.isReadOnly === false) {
        //   rect.addEventListener('click', this.rectClick);
        // }
      }
      return rect;
    },
    // rectClick(ev) {
    //   if (this.field_view_mode == 'validate') {
    //     this.showConnectionFromRect(ev);
    //   } else {
    //     marqueeClick()
    //   }
    // },
    prepareDataToDraw(field, connectionId, byPass) {
      const fieldObj = byPass ? byPass : this.getHTMLField(field);
      if (fieldObj) {
        if (this.page == field.page) {
          if (
            field.coords &&
            field.coords[0] &&
            field.coords[0].hasOwnProperty('x') &&
            field.coords[0].hasOwnProperty('y')
          ) {
            let startX = Math.round(this.imageWidth * field.coords[0].x);
            let startY = Math.round(this.imageHeight * field.coords[0].y);
            let endX = Math.round(this.imageWidth * field.coords[2].x);
            let endY = Math.round(this.imageHeight * field.coords[2].y);

            let width = endX - startX || 20;
            let height = endY - startY || 20;

            if (width < 0) {
              width *= -1;
              startX -= width;
            }
            if (height < 0) {
              height *= -1;
              startY -= height;
            }

            this.marqueeRect.x = startX;
            this.marqueeRect.y = startY;
            this.marqueeRect.width = width;
            this.marqueeRect.height = height;
            this.marqueeRect.connectionId = connectionId;

            this.rectangles.push(Object.assign({}, this.marqueeRect));
          }
        }
      }
    },
    prepareRectanglesForFields() {
      const data = this.record;
      if (!Array.isArray(data?.fields)) {
        return;
      }
      Array.from(data.fields).forEach((field) => {
        // One bad field must not abort the whole draw pass.
        try {
          this.prepareDataToDraw(field, field.name, false);
        } catch (err) {
          logError(err);
        }
      });
    },
    prepareRectanglesForAITable() {
      let tableObj = {};
      if (this.record.tables && this.record.tables[0]) {
        tableObj = this.record.tables[0];
      }

      if (!Array.isArray(tableObj.rows)) {
        return;
      }

      // Many rows can share the exact same coords (AI returns one bounding box
      // for several line items). Drawing one rect per row stacks them on top of
      // each other so only the last is visible. Draw one rect per coords group
      // and map every row's id to that rect, so clicking any of those rows
      // highlights the single drawn box (see highlightAITableRow).
      this.aiRowRectMap = {};
      const drawnByCoords = {};
      Array.from(tableObj.rows).forEach((row) => {
        const coordsKey = row.page + '|' + JSON.stringify(row.coords);
        if (!drawnByCoords[coordsKey]) {
          this.prepareDataToDraw(row, tableRowIdPreFix + row.id, true);
          drawnByCoords[coordsKey] = tableRowIdPreFix + row.id;
        }
        this.aiRowRectMap[tableRowIdPreFix + row.id] = drawnByCoords[coordsKey];
      });
    },

    prepareRectangles() {
      this.rectangles = [];
      this.prepareRectanglesForFields();
      if (this.has_ai_table) {
        this.prepareRectanglesForAITable();
      }
      this.redraw();
    },

    drawOverlay(connectionId, rectElement) {
      if (this.isConfirmationBoxDisable) {
        return;
      }

      this.connectionId = connectionId;
      this.removeExistingConfirmationOverlays();

      let heading = '';
      let subHeading = '';

      const tempHeadingStr = this.getOverlayHeadings();
      if (tempHeadingStr) {
        let tempHeading = tempHeadingStr.split(splitDelimiter);
        heading = tempHeading[0];
        subHeading = tempHeading[1];
      }

      // const input: HTMLInputElement | null = parentDiv.querySelector( this.componentType );

      // Getting input label

      // const width = ev.target.getAttribute('width');
      const dimensionDetails = this.getOffset(rectElement);

      const divOverlay = document.createElement('div');
      divOverlay.setAttribute('id', 'confirmation_overlay');
      divOverlay.style.position = 'absolute';
      divOverlay.style.zIndex = '999';
      divOverlay.style.left = dimensionDetails.left + 'px';
      divOverlay.style.top =
        (+dimensionDetails.top + +dimensionDetails.height + 6).toString() +
        'px';
      divOverlay.style.background = '#e2e2e2';
      divOverlay.style.color = '#898989';
      divOverlay.style.minHeight = '80px';
      divOverlay.style.minWidth = '100px';
      divOverlay.style.maxWidth = '50%';
      divOverlay.style.textAlign = 'center';
      divOverlay.style.padding = '5px 10px 5px 10px';
      divOverlay.style.letterSpacing = '1px';
      divOverlay.style.borderRadius = '7px';
      divOverlay.style.boxShadow = `0 1px 2px rgba(0,0,0,0.07),
            0 2px 4px rgba(0,0,0,0.07),
            0 4px 8px rgba(0,0,0,0.07),
            0 8px 16px rgba(0,0,0,0.07),
            0 16px 32px rgba(0,0,0,0.07),
            0 32px 64px rgba(0,0,0,0.07);`;

      let trashIcon = this.getTrashIcon(connectionId);
      const buttonsHtml = this.isReadOnly
        ? ''
        : `<div>
                        ${trashIcon}
                        <span class='divOverlayWrong'>
                          <span connectionId='${connectionId}' style='display: inline-block;border-radius: 50px;box-shadow: 0px 0px 2px #888;padding: 0.5em 0.6em;font-size:14px' class='material-icons cursor-pointer'>close</span>
                        </span>
                        <span id='divOverlayCorrect'>
                          <span style='display: inline-block;border-radius: 50px;box-shadow: 0px 0px 2px #888;padding: 0.5em 0.5em;font-size:14px' class='material-icons cursor-pointer'>check</span>
                        </span></div>`;
      divOverlay.innerHTML = `<div><b>${heading}</b></div><div><b style='font-size: 9px'>${subHeading}</b></div>
                        ${buttonsHtml}`;
      document.body.appendChild(divOverlay);
      $('#divOverlayCorrect')?.addEventListener('click', (e) => {
        this.removeExistingConfirmationOverlays();
        this.removeBordersFromRectangles();
        this.removeAllConnectionLines();
        this.selectNextField(connectionId);
        setTimeout(() => {
          this.enableOrDisableExportButton();
        }, 5);
      });

      let divOverlayWrongList =
        document.getElementsByClassName('divOverlayWrong');

      Array.from(divOverlayWrongList).forEach((element) => {
        element?.addEventListener('click', (e) => {
          this.connectionId = e.target.getAttribute('connectionId');
          if (!this.connectionId) {
            logError('connection id not found');
            return;
          }
          this.initTempFieldDelete();
          this.refreshCanvas();
          this.$forceUpdate();
          this.enableDrawing();
          // this.connectionId = '';
        });
      });

      $('#deleteRuleFromConnection')?.addEventListener('click', (e) => {
        this.connectionId = e.target.getAttribute('connectionId');
        if (!this.connectionId) {
          logError('connection id not found');
          return;
        }
        try {
          this.$refs['fieldsView'].deleteRule(this.connectionId);
          this.enableDrawing();
        } catch (err) {
          logError(err);
        }
      });
      // Aligning the div overlay in center
      try {
        const overlay = $('#confirmation_overlay');
        const overlayWidth = $('#confirmation_overlay')?.clientWidth;
        const rectWidth = dimensionDetails.width;
        const gapToDecreaseFromLeft = (+overlayWidth - +rectWidth) / 2;
        overlay.style.left =
          +dimensionDetails.left - +gapToDecreaseFromLeft + 'px';

        let totalExpectedHeight =
          +rectElement.getAttribute('width') +
          +rectElement.getAttribute('y') +
          overlay.offsetHeight;
        if (totalExpectedHeight >= this.screenshot.offsetHeight) {
          divOverlay.style.top =
            (+dimensionDetails.top - 6 - +overlay.offsetHeight).toString() +
            'px';
        }
        let scoreObj = null;
        let score_description = this.getScoreDescription(
          this.getFieldByIndex(connectionId),
        );
        if (score_description != null && score_description !== '') {
          scoreObj = {
            score: String(score_description),
            background: this.getColor(Number(score_description)),
          };
        }

        if (scoreObj) {
          setTimeout(() => {
            this.overlayForScore(overlay, scoreObj);
          }, 10);
        }
      } catch (err) {}
    },
    overlayForScore(rectElement, scoreObj) {
      let score = scoreObj.score;
      let background = scoreObj.background;

      const dimensionDetails = this.getOffset(rectElement);

      const divOverlay = document.createElement('div');
      divOverlay.setAttribute('id', 'score_overlay');
      divOverlay.style.position = 'absolute';
      divOverlay.style.zIndex = '999';
      divOverlay.style.left =
        (+dimensionDetails.left + dimensionDetails.width - 10).toString() +
        'px';
      divOverlay.style.top = (+dimensionDetails.top - 20).toString() + 'px';
      divOverlay.style.background = background;
      divOverlay.style.color = '#898989';
      divOverlay.style.fontSize = '14px';
      divOverlay.style.fontWeight = 'bold';
      divOverlay.style.letterSpacing = '2px';
      divOverlay.style.cursor = 'pointer';
      divOverlay.style.padding = '0.1em 0.6em';
      divOverlay.style.border = '1px solid #f5f5f5';
      divOverlay.style.borderRadius = '50px';
      divOverlay.innerHTML = `<div> <span  class='column-score-test' > ${score} </span> </div>`;
      document.body.appendChild(divOverlay);
    },
    getOffset(el) {
      const rect = el.getBoundingClientRect();
      return {
        left: rect.left + window.pageXOffset,
        right: rect.right + window.pageXOffset,
        top: rect.top + window.pageYOffset,
        width: rect.width || el.offsetWidth,
        height: rect.height || el.offsetHeight,
      };
    },
    /**
     * Will remove borders from rectangles, if have any
     */
    removeBordersFromRectangles() {
      let rects = document.body.getElementsByTagName('rect');
      for (let rect of rects) {
        rect.classList.remove('svg-stroke-border');
      }
    },
    /**
     * Will remove connection lines from whole page, if have any
     */
    removeAllConnectionLines() {
      const connectionLineElm = $('#connection_line');
      if (connectionLineElm) {
        connectionLineElm.remove();
      }
    },

    getScoreDescription(field) {
      let score_description = '';
      if (
        field &&
        field.hasOwnProperty('score_description') &&
        field.score_description !== '' &&
        field.score_description != null
      ) {
        score_description = field.score_description;
      }

      return String(score_description);
    },
    getTrashIcon(connectionId) {
      let field = this.getFieldByIndex(connectionId);
      let trashIcon = '';
      if (!field) {
        return trashIcon;
      }
      if (!field.deleted && field.rule) {
        trashIcon = `<span id='deleteRuleFromConnection'>
                <span connectionId='${connectionId}' style='display: inline-block;border-radius: 50px;box-shadow: 0px 0px 2px #888;padding: 0.5em 0.6em;font-size:14px' class='material-icons'>delete</span>
                </span>`;
      } else {
        trashIcon = `<span class='divOverlayWrong'>
                          <span connectionId='${connectionId}' style='display: inline-block;border-radius: 50px;box-shadow: 0px 0px 2px #888;padding: 0.5em 0.6em;font-size:14px' class='material-icons'>delete</span>
                        </span>`;
      }

      return trashIcon;
    },

    /**
     * Will allow user to draw rectangles on image when user reject div overlay
     */
    enableDrawing(removePreviousRect = false) {
      if (removePreviousRect) {
        this.rectangles.pop();
        this.redraw();
      }
      const draw = $('#draw');
      draw.classList.add('enableDrawingRectangle');
      const screenshot = $('.screenshot');
      screenshot.classList.add('cursor-crosshair');
    },
    /**
     * Will restrict user to draw rectangles on image
     */
    restrictDrawing() {
      const draw = $('#draw');
      draw.classList.remove('enableDrawingRectangle');

      const screenshot = $('.screenshot');
      screenshot.classList.remove('cursor-crosshair');
    },
    removeOverlayandLines() {
      this.removeBordersFromRectangles();
      this.removeAllConnectionLines();
      this.removeExistingConfirmationOverlays();
    },
    /**
     * Cancel overlay div. Nothing to do.
     */
    cancelOverlayDiv() {
      this.rectangles.pop();
      this.redraw();
      this.textApiResponse = null;
    },

    dblClickToSelect(ev) {
      // No field selected: nothing to extract into. Happens when the master
      // data lookup closes on the first click and the second one hits the image.
      if (!this.connectionId) {
        return;
      }
      this.rectCordinate = {
        startX: ev.layerX,
        startY: ev.layerY,
        endX: ev.layerX,
        endY: ev.layerY,
      };
      this.getTextByCoordinates(this.rectCordinate);
    },

    currentPage() {
      return this.page;
    },
    setImage() {
      if (
        this.record.hasOwnProperty('classification') &&
        this.record.classification.hasOwnProperty('classification_page')
      ) {
        this.page = this.record.classification.classification_page;
      }

      // BUG_FIX_8650: Add defensive check for missing images array
      // Prevents silent error when images are not yet loaded or missing
      if (
        !this.record.images ||
        !Array.isArray(this.record.images) ||
        this.record.images.length === 0
      ) {
        console.warn(
          'setImage: No images available in record',
          'doc_id=' + (this.record.doc_id || 'unknown'),
          'images=' + (this.record.images ? 'exists but empty' : 'missing'),
        );
        return;
      }

      let doc2_image_url = this.handleImageBaseURL(this.record.images);
      if (doc2_image_url !== '') {
        this.baseUrl = doc2_image_url;
      }

      this.images = cleanUpImagesUrl(this.record.images);

      // Ensure page index is valid
      const pageIndex = Math.max(0, Math.min(this.page - 1, this.record.images.length - 1));
      if (!this.record.images[pageIndex] || !this.record.images[pageIndex].path) {
        console.warn(
          'setImage: Invalid image at page index',
          'pageIndex=' + pageIndex,
          'doc_id=' + (this.record.doc_id || 'unknown'),
        );
        return;
      }

      this.image =
        this.baseUrl +
        '/' +
        cleanUpImagePath(this.record.images[pageIndex].path);
    },

    highlightRow(rectElement) {
      if (!rectElement) {
        return;
      }
      rectElement.classList.add('svg-stroke-border');
    },
    cleanRectangles() {
      // Now we have two rectangles of same connectionId
      // But we're sure that the rectangle we newly created will be at the end of rectangles array
      // Newly created rectangle
      const rect = this.rectangles[this.rectangles.length - 1];
      // filtered array will have two rects less than original one
      const filtered = this.rectangles.filter(function (value, index, arr) {
        return value.connectionId !== rect.connectionId;
      });
      this.rectangles = [];
      this.rectangles = JSON.parse(JSON.stringify(filtered));
      // Add newly created rectangle back to array and draw
      this.rectangles.push(rect);
    },

    // ==========================================================================================================================
    // below this line give funcations will be call by parent refernce ie child window will call them by parent reference
    saveResultWrapper(marqueeRect, rectCordinate) {
      this.marqueeRect = marqueeRect;
      this.rectCordinate = rectCordinate;
      this.rectangles.push(Object.assign({}, marqueeRect));
      this.saveOverlayResult();
    },
    dsiplayFieldInToView(connectionId) {
      const fieldElement = this.getElementToConnect($('#' + connectionId));
      this.scrollInToViewCenter(fieldElement);

      if (fieldElement) {
        fieldElement.classList.add('light-yellow-with-effect');
        setTimeout(() => {
          fieldElement.classList.remove('light-yellow-with-effect');
        }, 1000);
      }
    },
  },
};
